      "locationPrivacy": "ඔබගේ ස්ථානය මෙම සිතියමේ පෙන්වීමට සහ මධ්‍යගත කිරීමට පමණක් SAFEWAY බ්‍රව්සර අවසරය ඉල්ලයි. ඛණ්ඩාංක මෙම බ්‍රව්සර පටිත්තේ පමණක් පවතී; ඒවා සුරකින්නේ, පසුබිමට යවන්නේ හෝ වෙනත් පරිශීලකයන්ට පෙන්වන්නේ නැත. ඔබ \"දහුවගත් ස්ථානය භාවිත කරන්න\" යන්න පැහැදිලිව තෝරා පහතින් මෙහෙයුම් ප්‍රදේශයක් සුරකින එකම අවස්ථාව ඊට ව්‍යතිරේකයයි. පිටුවෙන් පිටවීමේදී, පටිත්ත සැඟවීමේදී, පිටවීමේදී හෝ අක්‍රීය කිරීමේදී ලුහුබැඳීම නවතී.",
